// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager(address(this));
    }

    function _run(address caller) internal {
        vm.assume(caller != address(c.optimisticAsserter()));
        bool reverted;
        try c.assertionDisputedCallback(bytes32(0)) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (caller == address(c.optimisticAsserter())));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
